-- 0015 · Importación de los sobrantes de los Excel LEFT OVERS (sep 2026)
-- Fuente: Datos/Left Overs (NAVE, JORGE JUAN, SANTA FELICIANA 10). Criterio acordado con el cliente:
--  · el Excel manda: cada día que trae el Excel queda EXACTAMENTE como el Excel
--    (se sustituyen los valores y se eliminan las líneas de pruebas hechas desde la app);
--  · el valor del Excel va a saved_qty (misma convención que la importación de feb-mar);
--  · los días importados quedan cerrados. Los días que no están en el Excel no se tocan.
-- Excluido: hojas '2026076' y 'merma' del Excel NAVE (copias exactas de Santa Feliciana),
-- NAVE '20260921' (copia idéntica de '20260914'), fechas futuras, 'Leche Priégola' y celdas
-- no numéricas. JJ '20260622': cabecera con fechas mal tecleadas -> fecha por columna.
-- Copia previa: Datos/Backups/sobrantes-antes-import-excel-2026-09-26.json
-- 3681 celdas en 238 días. Formato: 'producto:cantidad' separados por espacio.

create temporary table _prod (idx integer primary key, name text) on commit drop;

create temporary table _dias (loc text, day date, cells text) on commit drop;

create temporary table _excel_ids on commit drop as
select l.id as location_id, d.day, p.id as product_id, split_part(c, ':', 2)::numeric as qty
from _dias d
cross join lateral unnest(string_to_array(d.cells, ' ')) as c
join _prod x on x.idx = split_part(c, ':', 1)::integer
join public.products p on p.name = x.name and p.is_obrador and p.is_active
join public.locations l on l.name = case d.loc when 'SF' then 'SANTA FELICIANA 10'
  when 'NAVE' then 'LOS URQUIZA 17' when 'JJ' then 'NUEVA TIENDA' end;

do $$
declare n integer;
begin
  select count(*) into n from _excel_ids;
  if n <> 3681 then raise exception 'Import sobrantes: esperadas 3681 celdas, resueltas %', n; end if;
end $$;

select distinct location_id, day, 'closed', now() from _excel_ids
on conflict (location_id, session_date) do update
  set status = 'closed', closed_at = coalesce(public.daily_sessions.closed_at, now());

-- Líneas de pruebas de la app en días que cubre el Excel
delete from public.daily_product_entries d
using public.daily_sessions s
where d.daily_session_id = s.id
  and exists (select 1 from _excel_ids x where x.location_id = s.location_id and x.day = s.session_date)
  and not exists (select 1 from _excel_ids x where x.location_id = s.location_id
                  and x.day = s.session_date and x.product_id = d.product_id);

select s.id, x.product_id, x.qty, 0, null, null
from _excel_ids x
join public.daily_sessions s on s.location_id = x.location_id and s.session_date = x.day
on conflict (daily_session_id, product_id) do update
  set saved_qty = excluded.saved_qty, discarded_qty = 0, discard_reason = null, comment = null;
